//! The values-only design source has one compiler, shared by every platform.
use std::{collections::BTreeMap, fs, path::Path};

use anyhow::{Context, Result, ensure};
use serde::Deserialize;
use serde_json::{Value, json};

mod brand;
mod catalog;
mod fonts;
mod mockups;
mod site;
mod words;

const ANDROID: &str = "mobile/androidApp/src/main";
const IOS: &str = "mobile/iosApp";
const HEADER: &str =
    "// GENERATED by cargo xtask design. Edit design/tokens.toml, then regenerate.\n";

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Tokens {
    fonts: Vec<Font>,
    apps: BTreeMap<String, Accent>,
    states: BTreeMap<String, Accent>,
    lists: BTreeMap<String, String>,
    surfaces: BTreeMap<String, BTreeMap<String, String>>,
    brand: BTreeMap<String, String>,
    spacing: BTreeMap<String, f64>,
    radii: BTreeMap<String, f64>,
    geometry: BTreeMap<String, f64>,
    #[serde(rename = "type")]
    typography: BTreeMap<String, TypeStyle>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Font {
    family: String,
    name: String,
    weight: u16,
    postscript: String,
    file: String,
    android: String,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Accent {
    light: String,
    dark_fill: String,
    dark_text: String,
    light_tint: String,
    dark_tint: String,
    #[serde(default)]
    tile: Option<String>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct TypeStyle {
    family: String,
    size: f64,
    line_height: f64,
    weight: u16,
}

#[derive(Default)]
struct Artifacts(BTreeMap<String, Vec<u8>>);

impl Artifacts {
    fn text(&mut self, name: impl Into<String>, text: impl Into<String>) {
        self.0.insert(name.into(), text.into().into_bytes());
    }

    fn json(&mut self, name: impl Into<String>, value: &Value) -> Result<()> {
        self.text(name, format!("{}\n", serde_json::to_string_pretty(value)?));
        Ok(())
    }

    fn settle(self, root: &Path, check: bool) -> Result<usize> {
        let mut stale = Vec::new();
        for (name, expected) in &self.0 {
            let path = root.join(name);
            if fs::read(&path).ok().as_ref() == Some(expected) {
                continue;
            }
            if check {
                stale.push(name.as_str());
            } else {
                fs::create_dir_all(path.parent().context("artifact has no parent")?)?;
                fs::write(path, expected)?;
            }
        }
        ensure!(
            stale.is_empty(),
            "stale or missing artifacts; run cargo xtask design:\n{}",
            stale.join("\n")
        );
        Ok(self.0.len())
    }
}

pub fn generate(root: &Path, check: bool) -> Result<usize> {
    let tokens: Tokens = toml::from_str(&fs::read_to_string(root.join("design/tokens.toml"))?)
        .context("design/tokens.toml")?;
    tokens.validate()?;
    let mut out = Artifacts::default();
    let themes = [tokens.colors(false), tokens.colors(true)];
    for theme in &themes {
        for value in theme.values() {
            rgba(value)?;
        }
    }
    emit_resources(&tokens, &themes, &mut out)?;
    emit_themes(&tokens, &themes, &mut out)?;
    fonts::emit(root, &tokens, &mut out)?;
    site::emit(&tokens, &mut out)?;
    catalog::emit(root, &tokens, &mut out)?;
    words::emit(root, &mut out)?;
    brand::emit(&tokens, &mut out)?;
    mockups::emit(root, &tokens, &mut out)?;
    out.settle(root, check)
}

impl Tokens {
    fn validate(&self) -> Result<()> {
        for app in [
            "shell", "agenda", "notes", "people", "docs", "money", "locker", "health", "photos",
        ] {
            ensure!(self.apps.contains_key(app), "missing app palette {app}");
        }
        for state in ["danger", "warning", "success"] {
            ensure!(
                self.states.contains_key(state),
                "missing state palette {state}"
            );
        }
        for scheme in ["light", "dark"] {
            let surfaces = self
                .surfaces
                .get(scheme)
                .with_context(|| format!("missing {scheme} surfaces"))?;
            for name in [
                "page",
                "list",
                "card",
                "sheet",
                "sheet_card",
                "fill",
                "line",
                "edge",
                "ink",
                "body",
                "meta",
                "disabled",
                "white",
                "glass",
                "scrim",
            ] {
                rgba(
                    surfaces
                        .get(name)
                        .with_context(|| format!("missing {scheme}.{name}"))?,
                )?;
            }
        }
        ensure!(
            self.lists.len() == 8,
            "lists must use the single eight-colour palette"
        );
        let page = &self.surfaces["light"]["page"];
        let card = &self.surfaces["dark"]["card"];
        for (name, color) in self.apps.iter().chain(self.states.iter()) {
            ensure!(
                contrast(&color.light, page)? >= 4.5,
                "{name} light text needs 4.5:1"
            );
            ensure!(
                contrast(&color.dark_text, card)? >= 6.0,
                "{name} dark text needs 6:1"
            );
            ensure!(
                contrast(&color.dark_fill, &self.surfaces["dark"]["white"])? >= 4.5,
                "{name} fill needs 4.5:1 under white glyphs"
            );
            if let Some(tile) = &color.tile {
                ensure!(
                    contrast(tile, self.tile_ink(tile))? >= 4.5,
                    "{name} tile needs 4.5:1 under its glyph"
                );
            }
        }
        for (name, value) in &self.lists {
            ensure!(
                contrast(value, page)? >= 3.0 && contrast(value, card)? >= 3.0,
                "list {name} needs 3:1 in both schemes"
            );
        }
        for (name, style) in &self.typography {
            ensure!(
                style.size > 0.0 && style.line_height >= style.size,
                "invalid type geometry: {name}"
            );
            ensure!(
                self.fonts
                    .iter()
                    .any(|font| font.family == style.family && font.weight == style.weight),
                "no font for type role {name}"
            );
        }
        Ok(())
    }

    fn tile_ink(&self, tile: &str) -> &String {
        let white = &self.surfaces["light"]["white"];
        if contrast(tile, white).unwrap_or_default() >= 4.5 {
            white
        } else {
            &self.surfaces["light"]["ink"]
        }
    }

    fn colors(&self, dark: bool) -> BTreeMap<String, String> {
        let s = &self.surfaces[if dark { "dark" } else { "light" }];
        let mut colors = BTreeMap::new();
        for (role, source) in [
            ("bg", "page"),
            ("bgList", "list"),
            ("bgChrome", "sheet"),
            ("bgElev", "card"),
            ("bgSheetCard", "sheet_card"),
            ("bgHover", "fill"),
            ("bgPress", "fill"),
            ("bgSunken", "fill"),
            ("line", "line"),
            ("lineStrong", "edge"),
            ("text", "ink"),
            ("textSoft", "body"),
            ("textFaint", "meta"),
            ("textGhost", "meta"),
            ("textDisabled", "disabled"),
            ("textInv", "white"),
            ("onAccent", "white"),
            ("skel", "fill"),
            ("scrim", "scrim"),
            ("glass", "glass"),
        ] {
            colors.insert(role.to_owned(), s[source].clone());
        }
        for (prefix, accent) in self.apps.iter().chain(self.states.iter()) {
            let text = if dark {
                &accent.dark_text
            } else {
                &accent.light
            };
            let fill = if dark {
                &accent.dark_fill
            } else {
                &accent.light
            };
            let tint = if dark {
                &accent.dark_tint
            } else {
                &accent.light_tint
            };
            colors.insert(format!("{prefix}Text"), text.clone());
            colors.insert(format!("{prefix}Fill"), fill.clone());
            colors.insert(format!("{prefix}Tint"), tint.clone());
            colors.insert(format!("{prefix}OnStage"), accent.dark_text.clone());
            if let Some(tile) = &accent.tile {
                colors.insert(format!("{prefix}Tile"), tile.clone());
                colors.insert(format!("{prefix}OnTile"), self.tile_ink(tile).clone());
            }
        }
        for (key, value) in &self.lists {
            colors.insert(format!("list{}", upper_first(key)), value.clone());
        }
        for (key, value) in &self.brand {
            colors.insert(format!("brand{}", upper_first(key)), value.clone());
        }
        // Existing view roles resolve to the new semantic roles while individual
        // screens migrate. No colour value is owned by this alias table.
        for (alias, role) in [
            ("accent", "shellFill"),
            ("accentDeep", "shellFill"),
            ("accentFill", "shellFill"),
            ("accentDeepHover", "shellFill"),
            ("accentInkHover", "shellFill"),
            ("accentLight", "shellText"),
            ("accentSoft", "shellTint"),
            ("accentText", "shellText"),
            ("appIdentityText", "shellText"),
            ("attention", "warningText"),
            ("warning", "warningText"),
            ("danger", "dangerText"),
            ("net", "dangerText"),
            ("netHover", "dangerText"),
            ("netWash", "dangerTint"),
            ("success", "successText"),
            ("link", "agendaText"),
            ("focusRingColor", "agendaText"),
            ("bgSel", "agendaTint"),
            ("lineSel", "agendaText"),
            ("seam", "warningText"),
            ("cSlate", "listBlue"),
            ("cOchre", "listYellow"),
            ("cViolet", "listViolet"),
            ("cTeal", "listPetrol"),
            ("cIndigo", "listNavy"),
            ("cOlive", "listGraphite"),
            ("cAmber", "listRaspberry"),
            ("cRose", "listOrchid"),
            ("cForest", "listPetrol"),
        ] {
            colors.insert(alias.to_owned(), colors[role].clone());
        }
        for (role, source) in [
            ("stage", "page"),
            ("stageLine", "line"),
            ("stageSunken", "card"),
            ("onStage", "ink"),
            ("onStageSoft", "meta"),
        ] {
            colors.insert(role.to_owned(), self.surfaces["dark"][source].clone());
        }
        colors
    }
}

fn upper_first(value: &str) -> String {
    let mut chars = value.chars();
    chars.next().map_or_else(String::new, |c| {
        c.to_uppercase().collect::<String>() + chars.as_str()
    })
}

fn snake(value: &str) -> String {
    let mut out = String::new();
    for c in value.chars() {
        if c.is_ascii_uppercase() {
            out.push('_');
            out.push(c.to_ascii_lowercase());
        } else {
            out.push(c);
        }
    }
    out
}

fn rgba(hex: &str) -> Result<[u8; 4]> {
    ensure!(
        hex.starts_with('#') && matches!(hex.len(), 7 | 9),
        "expected #RRGGBB or #RRGGBBAA, got {hex}"
    );
    let mut channels = [255; 4];
    for (i, part) in hex.as_bytes()[1..].chunks(2).enumerate() {
        channels[i] = u8::from_str_radix(std::str::from_utf8(part)?, 16)?;
    }
    Ok(channels)
}

fn android_color(hex: &str) -> Result<String> {
    let [r, g, b, a] = rgba(hex)?;
    Ok(format!("{a:02X}{r:02X}{g:02X}{b:02X}"))
}

fn contrast(a: &str, b: &str) -> Result<f64> {
    let luminance = |hex: &str| -> Result<f64> {
        let [r, g, b, alpha] = rgba(hex)?;
        ensure!(alpha == 255, "contrast roles must be opaque");
        let linear = |value: u8| {
            let value = f64::from(value) / 255.0;
            if value <= 0.04045 {
                value / 12.92
            } else {
                ((value + 0.055) / 1.055).powf(2.4)
            }
        };
        Ok(0.2126 * linear(r) + 0.7152 * linear(g) + 0.0722 * linear(b))
    };
    let (a, b) = (luminance(a)?, luminance(b)?);
    Ok((a.max(b) + 0.05) / (a.min(b) + 0.05))
}

fn emit_resources(
    t: &Tokens,
    themes: &[BTreeMap<String, String>; 2],
    out: &mut Artifacts,
) -> Result<()> {
    let info = json!({"author":"xcode", "version":1});
    out.json(
        format!("{IOS}/Resources/Design.xcassets/Contents.json"),
        &json!({"info":info}),
    )?;
    for key in themes[0].keys() {
        let colors = [false, true].into_iter().map(|dark| {
            let [r,g,b,a] = rgba(&themes[usize::from(dark)][key])?;
            let mut color = json!({"idiom":"universal", "color":{"color-space":"srgb", "components":{
                "red":format!("0x{r:02X}"),"green":format!("0x{g:02X}"),"blue":format!("0x{b:02X}"),"alpha":format!("{:.6}", f64::from(a)/255.0)}}});
            if dark { color["appearances"] = json!([{"appearance":"luminosity", "value":"dark"}]); }
            Ok(color)
        }).collect::<Result<Vec<_>>>()?;
        out.json(
            format!("{IOS}/Resources/Design.xcassets/design_{key}.colorset/Contents.json"),
            &json!({"info":info,"colors":colors}),
        )?;
    }
    for (i, dir) in ["values", "values-night"].iter().enumerate() {
        let mut xml = String::from(
            "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<!-- GENERATED by cargo xtask design. -->\n<resources>\n",
        );
        for (name, hex) in &themes[i] {
            xml.push_str(&format!(
                "    <color name=\"design_{}\">#{}</color>\n",
                snake(name),
                android_color(hex)?
            ));
        }
        xml.push_str("</resources>\n");
        out.text(format!("{ANDROID}/res/{dir}/colors.xml"), xml);
    }
    let mut xml = String::from(
        "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<!-- GENERATED by cargo xtask design. -->\n<resources>\n",
    );
    for (kind, values) in [
        ("spacing", &t.spacing),
        ("radius", &t.radii),
        ("geometry", &t.geometry),
    ] {
        for (name, value) in values {
            // Durations and unitless icon ratios remain numeric constants in
            // the native theme; Android dimensions must describe lengths.
            if kind == "geometry"
                && matches!(
                    name.as_str(),
                    "durationOne"
                        | "durationTwo"
                        | "iconChipRadiusRatio"
                        | "iconChipTintDark"
                        | "iconChipTintLight"
                )
            {
                continue;
            }
            xml.push_str(&format!(
                "    <dimen name=\"design_{kind}_{}\">{value}dp</dimen>\n",
                snake(name)
            ));
        }
    }
    for (name, style) in &t.typography {
        xml.push_str(&format!(
            "    <dimen name=\"design_type_{}\">{}sp</dimen>\n",
            snake(name),
            style.size
        ));
        xml.push_str(&format!(
            "    <dimen name=\"design_line_{}\">{}sp</dimen>\n",
            snake(name),
            style.line_height
        ));
    }
    xml.push_str("</resources>\n");
    out.text(format!("{ANDROID}/res/values/dimens.xml"), xml);
    Ok(())
}

fn emit_themes(
    t: &Tokens,
    themes: &[BTreeMap<String, String>; 2],
    out: &mut Artifacts,
) -> Result<()> {
    let mut swift = format!(
        "{HEADER}import SwiftUI\n\npublic struct CentraidTypeStyle: Sendable {{\n    public let family: String\n    public let fontSize: CGFloat\n    public let lineHeight: CGFloat\n    public let weight: Int\n}}\n\npublic struct CentraidTheme: Sendable {{\n    public let scheme: String\n    public let colors: [String: Color]\n    public let effects: [String: String]\n    public let spacing: [String: CGFloat]\n    public let radii: [String: CGFloat]\n    public let type: [String: CentraidTypeStyle]\n}}\n"
    );
    let mut kotlin = format!(
        "{HEADER}package dev.centraid.design\n\npublic data class NativeTheme(\n    public val scheme: String,\n    public val colors: Map<String, Long>,\n    public val effects: Map<String, String>,\n    public val spacing: Map<String, Int>,\n    public val radii: Map<String, Int>,\n    public val type: Map<String, NativeTypeStyle>,\n)\n\npublic data class NativeTypeStyle(\n    public val family: String,\n    public val fontSize: Double,\n    public val lineHeight: Double,\n    public val weight: Int,\n)\n"
    );
    swift.push_str("\npublic let centraidColorRoles: [String] = [\n");
    kotlin.push_str("\npublic val NATIVE_COLOR_ROLES: List<String> = listOf(\n");
    for name in themes[0].keys() {
        swift.push_str(&format!("    \"{name}\",\n"));
        kotlin.push_str(&format!("    \"{name}\",\n"));
    }
    swift.push_str("]\n");
    swift.push_str(&fonts::swift(t));
    swift.push_str("public enum CentraidTokens {\n");
    kotlin.push_str(")\n\npublic val NATIVE_EFFECT_ROLES: List<String> = emptyList()\n");
    kotlin.push_str(&fonts::kotlin(t));
    kotlin.push_str("public object CentraidTokens {\n");
    let mut schemes = BTreeMap::new();
    for (i, scheme) in ["light", "dark"].iter().enumerate() {
        swift.push_str(&format!("    public static let {scheme} = CentraidTheme(\n        scheme: \"{scheme}\",\n        colors: [\n"));
        kotlin.push_str(&format!("    public val {scheme}: NativeTheme = NativeTheme(\n        scheme = \"{scheme}\",\n        colors = mapOf(\n"));
        for (key, value) in &themes[i] {
            swift.push_str(&format!(
                "            \"{key}\": Color(\"design_{key}\"),\n"
            ));
            kotlin.push_str(&format!(
                "            \"{key}\" to 0x{}L,\n",
                android_color(value)?
            ));
        }
        swift.push_str("        ],\n        effects: [:],\n");
        kotlin.push_str("        ),\n        effects = emptyMap(),\n");
        for (kind, values) in [("spacing", &t.spacing), ("radii", &t.radii)] {
            swift.push_str(&format!("        {kind}: [\n"));
            kotlin.push_str(&format!("        {kind} = mapOf(\n"));
            for (key, value) in values {
                ensure!(
                    value.fract() == 0.0 && *value >= 0.0,
                    "{kind}.{key} must be a nonnegative integer"
                );
                swift.push_str(&format!("            \"{key}\": {value},\n"));
                kotlin.push_str(&format!("            \"{key}\" to {value},\n"));
            }
            swift.push_str("        ],\n");
            kotlin.push_str("        ),\n");
        }
        swift.push_str("        type: [\n");
        kotlin.push_str("        type = mapOf(\n");
        let mut types = BTreeMap::new();
        for (key, style) in &t.typography {
            let TypeStyle {
                family,
                size,
                line_height,
                weight,
            } = style;
            swift.push_str(&format!("            \"{key}\": CentraidTypeStyle(family: \"{family}\", fontSize: {size}, lineHeight: {line_height}, weight: {weight}),\n"));
            kotlin.push_str(&format!("            \"{key}\" to NativeTypeStyle(family = \"{family}\", fontSize = {size:.1}, lineHeight = {line_height:.1}, weight = {weight}),\n"));
            types.insert(key, json!({"family":family,"fontSize":size,"lineHeight":line_height,"weight":weight.to_string()}));
        }
        swift.push_str("        ]\n    )\n");
        kotlin.push_str("        ),\n    )\n");
        schemes.insert(scheme, json!({"scheme":scheme,"colors":themes[i],"spacing":t.spacing,"radii":t.radii,"type":types}));
    }
    swift.push_str("}\n");
    kotlin.push_str("}\n");
    out.text(format!("{IOS}/Design/Theme.swift"), swift);
    out.text(
        format!("{ANDROID}/kotlin/dev/centraid/android/design/Tokens.kt"),
        kotlin,
    );
    let roles: BTreeMap<_, _> = themes[0]
        .keys()
        .map(|name| (name, format!("--{}", snake(name).replace('_', "-"))))
        .collect();
    out.json(
        "design/native-theme.json",
        &json!({"$generatedBy":"cargo xtask design","schemes":schemes,"colorRoleContract":roles}),
    )?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn token_source_enforces_accessible_app_state_and_list_colours() {
        let mut tokens: Tokens =
            toml::from_str(include_str!("../../../design/tokens.toml")).expect("token source");
        tokens.validate().expect("accessible palettes");
        tokens.apps.get_mut("agenda").expect("agenda").dark_text =
            tokens.surfaces["dark"]["card"].clone();
        assert!(
            tokens
                .validate()
                .expect_err("invisible text")
                .to_string()
                .contains("agenda dark text")
        );
    }

    #[test]
    fn check_detects_missing_and_changed_outputs_without_mutating_them() {
        let dir = tempfile::tempdir().expect("tempdir");
        let make = || {
            let mut out = Artifacts::default();
            out.text("a/output", "expected");
            out
        };
        assert!(make().settle(dir.path(), true).is_err());
        assert!(!dir.path().join("a").exists());
        make().settle(dir.path(), false).expect("write");
        make().settle(dir.path(), true).expect("clean");
        fs::write(dir.path().join("a/output"), "edited").expect("edit");
        assert!(make().settle(dir.path(), true).is_err());
        assert_eq!(
            fs::read_to_string(dir.path().join("a/output")).expect("read"),
            "edited"
        );
    }

    #[test]
    fn alpha_is_last_in_tokens_and_first_in_android_resources() {
        assert_eq!(android_color("#12345678").expect("valid color"), "78123456");
        assert_eq!(android_color("#abcdef").expect("valid color"), "FFABCDEF");
        for invalid in ["red", "#fff", "#xxxxxx", "var(--ink)"] {
            assert!(rgba(invalid).is_err());
        }
    }
}
